let camX=0,camY=0;
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}function text(s,x,y,size=8,color='#e8e2cf',align='left'){ctx.font=`bold ${size}px ui-monospace,monospace`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(s,Math.round(x),Math.round(y))}
function draw(){if(!game)return;const dpr=Math.min(devicePixelRatio||1,2),sx=canvas.width/W,sy=canvas.height/H;ctx.setTransform(sx,0,0,sy,0,0);ctx.fillStyle='#11191d';ctx.fillRect(0,0,W,H);const g=game,p=g.player;camX=clamp(p.x-W/2,0,worldW-W);camY=clamp(p.y-H/2,0,worldH-H);if(g.shake>0){camX+=rnd(-2,2);camY+=rnd(-2,2)}ctx.save();ctx.translate(-Math.floor(camX),-Math.floor(camY));
 // Apartment floor and tiled rooms
 for(let r=0;r<3;r++){const bx=r*480;rect(bx,30,480,worldH-30,'#313b3a');for(let x=bx;x<bx+480;x+=20)for(let y=30;y<worldH;y+=20){rect(x,y,19,19,((x+y)/20|0)%2?'#34403e':'#394440');rect(x+1,y+1,17,17,'#35403d')}
 // Outer wall/window masonry
 rect(bx,27,480,9,'#66706a');rect(bx,worldH-9,480,9,'#626d67');rect(bx,27,8,worldH-27,'#66706a');rect(bx+472,27,8,worldH-27,'#66706a');
 for(let wx=bx+40;wx<bx+450;wx+=90){rect(wx,29,34,5,'#8bd2d0');rect(wx+3,30,28,2,'#b1e6d9');rect(wx+15,28,2,7,'#84908a')}
 // inner wall dividers, corridor gaps
 for(const wy of [108,255,402]){rect(bx+8,wy,176,7,'#65706a');rect(bx+211,wy,261,7,'#65706a');rect(bx+183,wy-2,28,12,'#b48752');rect(bx+185,wy,24,7,'#c29b60')}
 // furniture blocks
 for(let i=0;i<3;i++){let fx=bx+55+i*137,fy=67+(i%2)*154;rect(fx,fy,47,28,'#59483b');rect(fx+3,fy+3,41,21,'#79614a');rect(fx+6,fy+5,35,15,'#997759');rect(fx+7,fy+6,33,12,'#61726b');rect(fx,fy+25,4,4,'#352f2a');rect(fx+43,fy+25,4,4,'#352f2a')}
 for(let i=0;i<2;i++){let tx=bx+86+i*211,ty=169;rect(tx,ty,24,30,'#514a3e');rect(tx+3,ty+3,18,24,'#71634b');rect(tx+6,ty+6,12,18,'#8f774b');rect(tx+8,ty+8,8,14,'#5d7358')}
 }
 // Structural separation walls with open doors
 for(let b=480;b<worldW;b+=480){rect(b-5,30,10,75,'#626e69');rect(b-5,117,10,135,'#626e69');rect(b-5,264,10,133,'#626e69');rect(b-5,409,10,131,'#626e69');rect(b-5,106,10,12,'#c69b58');rect(b-5,252,10,12,'#c69b58');rect(b-5,397,10,12,'#c69b58')}
 // Exit marker
 rect(worldW-85,109,47,57,g.exitOpen?'#345440':'#463d2d');rect(worldW-80,113,37,48,g.exitOpen?'#5ea66d':'#867043');rect(worldW-74,119,24,37,g.exitOpen?'#aad780':'#cfac62');rect(worldW-51,136,3,4,'#413e32');text('EXIT',worldW-62,101,8,g.exitOpen?'#aaf191':'#e9c264','center');
 for(const pu of g.powerups){if(pu.used)continue;const bob=Math.sin(worldTime*4)*2;rect(pu.x-8,pu.y-8+bob,16,16,'#e1cc66');rect(pu.x-5,pu.y-5+bob,10,10,'#fff1a0');text(pu.kind==='coolant'?'C':'+',pu.x,pu.y+bob,9,'#566050','center')}
 // Fires with animated pixel flames and states
 for(const f of g.fires){if(!f.alive)continue;const pulse=Math.sin(worldTime*8+f.x)*2,rad=f.r+pulse;ctx.fillStyle=`rgba(255,87,25,${.12+f.heat*.15})`;ctx.beginPath();ctx.arc(f.x,f.y,rad+10,0,Math.PI*2);ctx.fill();rect(f.x-rad*.8,f.y-rad*.35,rad*1.6,rad*.9,'#9b3429');rect(f.x-rad*.55,f.y-rad*.7,rad*.65,rad,'#e64827');rect(f.x+rad*.05,f.y-rad*.9,rad*.6,rad*1.05,f.state===2?'#ff9b36':'#f46b2d');rect(f.x-rad*.22,f.y-rad*.5,rad*.5,rad*.7,'#ffd16a');if(f.foamed>0){rect(f.x-rad,f.y-rad,rad*2,4,'#dbe7be');f.foamed-=.016}}
 for(const c of g.civs){if(c.state==='saved'||c.carried)continue;const cx=c.x,cy=c.y;rect(cx-8,cy-5,16,13,'#6b4035');rect(cx-5,cy-7,10,9,'#efc995');rect(cx-5,cy+4,4,7,'#4e6770');rect(cx+2,cy+4,4,7,'#4e6770');rect(cx-7,cy-8,14,3,c.kind==='freeze'?'#9cc7d1':'#d18b58');if(c.kind==='freeze'&&c.state==='trapped')text('!',cx,cy-18,9,'#ffdb7c','center');if(c.kind==='runner')text('»',cx+12,cy-5,9,'#e7d28f','center');if(dist(p,c)<37){rect(cx-18,cy-24,36,9,'#17201eee');text(c.state==='following'?'FOLLOW':'ACTION',cx,cy-20,6,'#ffe5ac','center')}}
 for(const e of g.enemies){if(e.hp<=0)continue;const c=e.frozen>0?'#99edfa':e.sticky>0?'#c5d886':e.type==='ember'?'#db6038':'#a85e3d';rect(e.x-8,e.y-8,16,16,'#443933');rect(e.x-6,e.y-8,12,4,'#312a2b');rect(e.x-6,e.y-5,12,10,c);rect(e.x-4,e.y-1,3,3,'#fff19b');rect(e.x+2,e.y-1,3,3,'#fff19b');rect(e.x-5,e.y+5,4,4,'#2f3030');rect(e.x+2,e.y+5,4,4,'#2f3030');for(let h=0;h<e.hp;h++)rect(e.x-6+h*7,e.y-13,5,2,'#ef6650')}
 for(const fx of g.fx){if(fx.shot){rect(fx.x-3,fx.y-3,7,7,fx.color);rect(fx.x-1,fx.y-1,3,3,'#fff7c6')}else{rect(fx.x-2,fx.y-2,4,4,fx.color)}}
 // firefighter
 if(!p.invuln||Math.floor(worldTime*12)%2===0){rect(p.x-8,p.y-4,16,14,'#bb893f');rect(p.x-7,p.y-1,14,10,'#f0c64e');rect(p.x-5,p.y-7,10,8,'#e9b888');rect(p.x-8,p.y-10,16,5,'#a9302e');rect(p.x-5,p.y-13,11,5,'#e64635');rect(p.x-3,p.y-6,2,2,'#252726');rect(p.x+2,p.y-6,2,2,'#252726');rect(p.x-7,p.y+9,5,4,'#39484b');rect(p.x+2,p.y+9,5,4,'#39484b');rect(p.x+7,p.y+1,7,4,'#514a3f');if(p.carry){rect(p.x-4,p.y-17,8,4,'#f4c38e');rect(p.x-6,p.y-21,12,4,'#c97450')}}
 ctx.restore();drawHUD();
}

function drawHUD(){const g=game,p=g.player;ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);rect(0,0,W,30,'#101719eF');rect(0,29,W,1,'#69746b');text('MR. RESCUE',8,9,8,'#f1d88f');text('FLOOR 01',8,21,6,'#92a19a');text(`SCORE ${String(g.score).padStart(5,'0')}`,96,10,8,'#f4e7ca');text(`RESCUE ${g.rescued}/3`,96,21,7,'#c7e4bf');text('HEAT',202,10,6,'#e1d4b8');rect(232,6,79,8,'#394441');rect(233,7,Math.max(1,77*clamp(p.heat,0,1)),6,p.heat>.78?'#ed4b31':p.heat>.5?'#e7a63e':'#55b6a0');text('♥'.repeat(Math.max(0,p.health))+'♡'.repeat(Math.max(0,3-p.health)),202,22,8,'#fc6960');text(`GRADE ${g.score>1100?'S':g.score>760?'A':g.score>430?'B':'C'}`,319,10,7,'#f1d983');text(`CIVILIANS ${g.remaining}`,319,21,6,'#d7ded0');
 const a=agents[p.agent];rect(365,4,109,23,'#222c2d');rect(366,5,3,21,a.color);text(a.name,374,11,8,a.color);text(`${p.ammo[p.agent]} / ${agents[p.agent].ammo}`,374,21,7,'#e9ead8');
 rect(0,H-38,W,38,'#101719d9');rect(0,H-38,W,1,'#59645e');
 // persistent touch controls
 rect(12,H-33,73,27,'#273337');rect(13,H-32,71,25,'#4a554b');text('AGENT',48,H-23,6,'#d7d4be','center');text('◀  SWAP  ▶',48,H-13,7,'#f3d16f','center');
 rect(W-84,H-35,70,30,g.exitOpen&&p.x>worldW-120?'#387650':'#994238');rect(W-82,H-33,66,26,g.exitOpen&&p.x>worldW-120?'#57925a':'#c25743');text(p.carry?'DROP / EXIT':p.x>worldW-100?'EXIT':'ACTION',W-49,H-21,7,'#fff0d3','center');text('TAP',W-49,H-10,5,'#ffdbab','center');
 if(p.coolant>0){rect(152,H-32,55,18,'#265b69');text(`COOL ${Math.ceil(p.coolant)}s`,179,H-23,6,'#a8f4f4','center')}if(p.overcharge>0){rect(211,H-32,62,18,'#655323');text(`OVERCHARGE`,242,H-23,6,'#ffe97b','center')}
 if(g.messageTime>0){const width=Math.min(W-40,Math.max(120,g.message.length*5));rect((W-width)/2,37,width,15,'#15201eeb');text(g.message,W/2,44,7,'#f2dea1','center')}
 // touch joysticks appear only while engaged
 for(const name of ['move','aim']){const j=joysticks[name];if(!j)continue;const x=j.sx,y=j.sy;ctx.globalAlpha=.72;ctx.fillStyle=name==='move'?'#9bd8c4':'#e6a783';ctx.beginPath();ctx.arc(x,y,29,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.85;ctx.strokeStyle='#f2ecd0';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,29,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#f3e7c4';ctx.beginPath();ctx.arc(x+j.x*20,y+j.y*20,11,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;if(name==='aim'&&Math.hypot(j.x,j.y)>.2){ctx.strokeStyle='#ffc86c';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+j.x*27,y+j.y*27);ctx.stroke()}}
 if(g.won||g.lost){rect(0,0,W,H,'#0c1112cf');rect(85,67,310,137,'#192326');rect(88,70,304,131,'#263232');text(g.won?'FLOOR CLEARED':'CREW DOWN',W/2,91,19,g.won?'#c6eb9a':'#ff7161','center');text(g.won?`GRADE ${g.grade}  •  SCORE ${g.score}`:`SCORE ${g.score}  •  RESCUED ${g.rescued}`,W/2,118,9,'#f5e5c4','center');text('TAP ACTION TO RUN AGAIN',W/2,153,8,'#e6b44d','center');text('BEST TIME IS ALWAYS THE NEXT ONE',W/2,177,6,'#9baba2','center')}
}
function coords(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}}
function setJoy(j,p){const dx=p.x-j.sx,dy=p.y-j.sy,m=Math.hypot(dx,dy),n=Math.min(m,34);j.x=m?dx/m*n/34:0;j.y=m?dy/m*n/34:0;j.active=m>5}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);const q=coords(e);if(!started)return;
 if(game.won||game.lost){if(q.y>H-46&&q.x>W-100){newGame();return}if(q.y>H-46){newGame();return}}
 if(q.y>H-42){if(q.x<100){cycle();return}if(q.x>W-100){interact();return}}
 if(q.x<W*.5){const j={sx:clamp(q.x,34,W-34),sy:clamp(q.y,38,H-55),x:0,y:0,id:e.pointerId,active:true};joysticks.move=j;pointerActions.set(e.pointerId,'move');setJoy(j,q)}else{const j={sx:q.x,sy:q.y,x:0,y:0,id:e.pointerId,active:true};joysticks.aim=j;pointerActions.set(e.pointerId,'aim');setJoy(j,q)} });
canvas.addEventListener('pointermove',e=>{const type=pointerActions.get(e.pointerId);if(!type)return;e.preventDefault();const j=joysticks[type];if(j)setJoy(j,coords(e))});
function release(e){const type=pointerActions.get(e.pointerId);if(!type)return;pointerActions.delete(e.pointerId);joysticks[type]=null}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
// Keyboard is optional; the full loop is playable entirely by touch.
addEventListener('keydown',e=>{if(!started){if(e.key===' '||e.key==='Enter')start();return}if(['1','2','3','4'].includes(e.key))game.player.agent=Number(e.key)-1;if(e.key===' '||e.key==='e')interact();if(e.key==='ArrowRight')game.player.x+=10;if(e.key==='ArrowLeft')game.player.x-=10});
function loop(now){if(!started)return;const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(loop)}
// Idle dispatch-screen rendering while waiting at the title card.
ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);ctx.fillStyle='#11191d';ctx.fillRect(0,0,W,H);
})();
</script></body></html>

