function coords(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}}function setJoy(j,q){const dx=q.x-j.sx,dy=q.y-j.sy,m=Math.hypot(dx,dy),n=Math.min(m,34);j.x=m?dx/m*n/34:0;j.y=m?dy/m*n/34:0;j.active=m>5}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);const q=coords(e);if(!started)return;if((game.won||game.lost)&&q.y>H-46){newGame();return}if(q.y>H-42){if(q.x<100){cycle();return}if(q.x>W-100){interact();return}}if(q.x<W*.5){const j={sx:clamp(q.x,34,W-34),sy:clamp(q.y,38,H-55),x:0,y:0,id:e.pointerId,active:true};joysticks.move=j;pointers.set(e.pointerId,'move');setJoy(j,q)}else{const j={sx:q.x,sy:q.y,x:0,y:0,id:e.pointerId,active:true};joysticks.aim=j;pointers.set(e.pointerId,'aim');setJoy(j,q)}});canvas.addEventListener('pointermove',e=>{const k=pointers.get(e.pointerId);if(k){e.preventDefault();setJoy(joysticks[k],coords(e))}});function release(e){const k=pointers.get(e.pointerId);if(k){pointers.delete(e.pointerId);joysticks[k]=null}}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
// Keyboard is optional; the full loop is playable entirely by touch.
addEventListener('keydown',e=>{if(!started){if(e.key===' '||e.key==='Enter')start();return}if(['1','2','3','4'].includes(e.key))game.player.agent=Number(e.key)-1;if(e.key===' '||e.key==='e')interact()});function loop(t){if(!started)return;const dt=Math.min(.04,(t-last)/1000||0);last=t;now=t/1000;update(dt);draw();requestAnimationFrame(loop)}
ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);ctx.fillStyle='#11191d';ctx.fillRect(0,0,W,H);
})();</script></body></html>

